class Dama:
    def __init__(self):
        self.board = [[" " for _ in range(8)] for _ in range(8)]
        self.setup_board()

    def setup_board(self):
        pieces = ["b", "r"]
        for i in range(3):
            for j in range(8):
                if (i+j) % 2 == 1:
                    self.board[i][j] = pieces[0]
        for i in range(5, 8):
            for j in range(8):
